node -e '
const {parse}=require("csv-parse/sync");const fs=require("fs");
let rows=[];for(const f of fs.readdirSync("data/feedbacks").filter(f=>f.endsWith(".csv")).sort())rows.push(...parse(fs.readFileSync("data/feedbacks/"+f),{columns:true,bom:true}));
const g=new Map();for(const r of rows){const id=r.ID.trim();const o=g.get(id)||{lab:[],unl:[]};const l2=r["Vfc level2 Name"].trim();(l2&&l2!=="no_class_found"?o.lab:o.unl).push(r["Feedback Type"].trim());g.set(id,o)}
